//! Every parser a command line ends in, with its actions, as argparse saw
//! them (recorded from the former Python front end; edited by hand since,
//! together with help_text.rs).
pub const TOP_USAGE: &str = "usage: tmiki [-h] [--version]\n             {init,status,add,commit,log,show,diff,ls-layers,branch,switch,restore,checkout,reset,rm,mv,tag,remote,fetch,push,pull,clone,merge,stash,hook,gc,recover,reflog,config,plugin} ...\n";
/// The top parser's subcommands (`choices` of its subparsers action), and
/// those of the parsers with subparsers of their own.
pub const TOP_CHOICES: &[&str] = &["init", "status", "add", "commit", "log", "show", "diff", "ls-layers", "branch", "switch", "restore", "checkout", "reset", "rm", "mv", "tag", "remote", "fetch", "push", "pull", "clone", "merge", "stash", "hook", "gc", "recover", "reflog", "config", "plugin"];
pub const NESTED: &[(&str, &[&str])] = &[("remote", &["add", "remove", "rm", "rename", "set-url"]), ("stash", &["push", "save", "list", "apply", "pop", "drop", "clear"]), ("hook", &["list", "run"]), ("plugin", &["add", "list", "prepare", "reimport", "trust", "remove", "dev", "new", "build", "test", "doctor", "install"])];

pub struct PAct {
    pub opts: &'static [&'static str],
    /// "0", "1" (nargs None), "?", "*" or "+"
    pub nargs: &'static str,
    pub choices: Option<&'static [&'static str]>,
    pub int: bool,
    pub required: bool,
    /// `_get_action_name(action)`
    pub name: &'static str,
    pub help: bool,
    /// `_get_values(action, [])` raises nothing (nargs "?" / "*")
    pub empty_ok: bool,
    /// indices of the actions a mutually exclusive group forbids with it
    pub conflicts: &'static [usize],
}

pub struct PParser {
    pub path: &'static [&'static str],
    pub prog: &'static str,
    pub usage: &'static str,
    pub actions: &'static [PAct],
}

